using System;
using System.Drawing;
using System.IO;
using System.Linq;
namespace DoomSNESed {
    public static class AudioAdvancedTests {
        static void Check(bool value,string message){Bin.Require(value,"Audio 0.6: "+message);}
        public static void Run(string path,string output){string data=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-data"),dir=Path.Combine(output,"audio-06");Directory.CreateDirectory(dir);var rom=new Rom(path,data);var input=new ImportedMusic{Name="Native bank test",Seconds=2,Report="2 notes"};input.Notes.Add(new MusicNote{Start=0,End=1.5,Channel=0,Program=30,Key=60,Velocity=100});input.Notes.Add(new MusicNote{Start=.1,End=1.5,Channel=1,Program=34,Key=36,Velocity=100});int rate;
            foreach(var bank in MusicBank.All(rom.Bytes)){var settings=new MusicSettings{Bank=bank.Module,Origin=bank.Origin,Song=bank.Song};foreach(var group in input.Notes.GroupBy(n=>new{n.Channel,n.Program}))settings.Assignments.Add(new MusicAssignment{Channel=group.Key.Channel,Program=group.Key.Program,Patch=MusicBank.Closest(bank,group.First())});var song=MusicImport.Convert(input,"E1M1",6,0,true,settings);AudioBuild.ValidateMusic(song);var pcm=NativeAudio.Render(rom.Bytes,MusicBank.PreviewRam(rom.Bytes,song),0,bank.Song,.5,out rate);Check(pcm.Max(s=>Math.Abs((int)s))>100,"native SPC bank "+bank.Module+" plays its assigned patches");}
            var mapping=MusicBank.Automatic(rom.Bytes,input);var music=MusicOptimize.Fit(input,"E1M1",6,0,true,mapping);Check(music.Sequence.Length<=0xb490-mapping.Origin&&music.Source==input,"auto matching and full-length fitting preserve editable source notes");
            var drums=new ImportedMusic{Name="Drums",Seconds=1,Report=""};foreach(int key in new[]{36,38,42})drums.Notes.Add(new MusicNote{Channel=9,Program=0,Key=key,Start=(key-36)*.03,End=.8,Velocity=100});var drumSettings=MusicBank.Automatic(rom.Bytes,drums);Check(drumSettings.Assignments.Count==3&&drumSettings.Assignments.Select(a=>a.Key).Distinct().Count()==3&&drumSettings.Assignments.Select(a=>a.Patch).Distinct().Count()==3,"GM kick/snare/hi-hat retain independent native assignments");
            var dense=new ImportedMusic{Name="Dense long test",Seconds=600,Report="Dense test"};for(int i=0;i<24000;i++)dense.Notes.Add(new MusicNote{Start=i*.025,End=i*.025+.08,Key=48+i%24,Velocity=40+i%80,Channel=i%6,Program=30});var fitted=MusicOptimize.Fit(dense,"E1M2",6,0,true,new MusicSettings());Check(fitted.Sequence.Length<=9383&&fitted.Seconds>1&&fitted.Report.Contains("Auto fit"),"complex long score is reduced and bounded with an explicit report");
            var slot=AudioRom.Sounds(rom.Bytes,data).Single(s=>s.Wave==10);var original=NativeAudio.Render(rom.Bytes,NativeAudio.SoundRam(rom.Bytes,slot,slot.Effects[0],null),1,slot.Effects[0],.25,out rate);Check(rate>8000&&rate<10000&&original.Max(s=>Math.Abs((int)s))>100,"native pistol preview measures original pitch and envelope");string wave=Path.Combine(dir,"tone.wav");short[] tone=Enumerable.Range(0,2205).Select(i=>(short)(Math.Sin(i*2*Math.PI*440/11025)*22000)).ToArray();File.WriteAllBytes(wave,WavImport.WaveFile(tone,11025));var sound=WavImport.Convert(wave,slot,false,false,false,false,rate);Check(Math.Abs(WavImport.Decode(sound.Data).Length/(double)rate-.2)<.003,"WAV compensation preserves real playback duration at effect-specific pitch");sound.Effect=slot.Effects[0];
            rom.Project.RetailAssets=true;rom.Project.Audio.Music.Add(music);rom.Project.Audio.Sounds.Add(sound);for(int id=3;id<=5;id++){using(var bitmap=new Bitmap(256,224)){using(var g=Graphics.FromImage(bitmap)){g.Clear(Color.Red);g.FillRectangle(Brushes.Green,0,0,128,112);g.FillRectangle(Brushes.Blue,128,112,128,112);}string png=Path.Combine(dir,"episode-"+(id-2)+".png");bitmap.Save(png);rom.Project.Graphics.Add(ScreenAssets.Import(new NativeGraphic{Screen=id},png));}}
            for(int episode=1;episode<=3;episode++)rom.Project.Texts.Add(new TextReplacement{Id=episode,Text="DEVELOPER TEST EPISODE "+episode+"\r\n\r\nCUSTOM STORY TEXT"});
            for(int page=1;page<=2;page++){var lines=TextAssets.ReadCredits(rom.Bytes,page);lines[0].Text="DEVELOPER PAGE "+page;lines[0].Column=1;rom.Project.Texts.Add(new TextReplacement{Id=page+3,Lines=lines});}
            bool rejected=false;try{TextAssets.EncodeStory(1,new string('X',31));}catch(InvalidDataException){rejected=true;}Check(rejected,"text outside the native font grid is rejected");rejected=false;try{TextAssets.EncodeStory(1,string.Join("\n",Enumerable.Repeat(new string('X',30),24).ToArray()));}catch(InvalidDataException){rejected=true;}Check(rejected,"ending byte allocation is enforced");
            byte[] image=rom.Compile();Check(image.Length==0x400000&&image[0x7fd7]==12,"ROM-only assets use a correct 4 MiB header");foreach(var section in rom.Sections.Where(s=>s.Size>0))Check(rom.Bytes.Skip(section.Start).Take(section.Size).SequenceEqual(image.Skip(section.Start).Take(section.Size)),"retail map bytes preserved: "+section.Name);Check(rom.Bytes.Skip(0x1ffbc6).Take(27).SequenceEqual(image.Skip(0x1ffbc6).Take(27))&&rom.Bytes[0x1ffb4e]==image[0x1ffb4e]&&rom.Bytes[0x1ffb55]==image[0x1ffb55],"original progression and episode difficulty gates preserved");
            foreach(var replacement in rom.Project.Texts){if(replacement.Id<=3)Check(TextAssets.Story(image,replacement.Id)==replacement.Text,"native ending text round-trip");else Check(TextAssets.ReadCredits(image,replacement.Id-3)[0].Text==replacement.Lines[0].Text,"credits strings and layouts round-trip independently");using(var preview=TextAssets.Preview(rom,replacement.Id,replacement,rom.Project.Graphics))preview.Save(Path.Combine(dir,"text-preview-"+replacement.Id+".png"));}
            for(int id=3;id<=5;id++)using(var bitmap=ScreenAssets.OriginalImage(image,id)){Check(bitmap.GetPixel(20,20).G>100&&bitmap.GetPixel(200,180).B>100,"episode "+(id-2)+" native 4bpp import is upright and uses replaced palette");}
            rom.SavePatch(Path.Combine(dir,"retail-assets.dse"),image);rom.SaveProject(Path.Combine(dir,"retail-assets.sned"));Bin.Atomic(Path.Combine(dir,"retail-assets.sfc"),image);var reopened=new Rom(path,data);reopened.LoadProject(Path.Combine(dir,"retail-assets.sned"));Check(reopened.Compile().SequenceEqual(image),"retail project, MIDI source and instrument settings reopen exactly");Check(Bin.Hex(Bin.Hash(rom.Bytes))==Rom.Identity,"original source ROM unchanged");
            for(int episode=1;episode<=3;episode++){var campaign=new Rom(path,data);campaign.LoadProject(Path.Combine(output,"native-campaign.sned"));Map room=campaign.Project.Maps.Single(m=>m.Slot==0);int storage=episode==2?9:0;if(storage!=0){campaign.Project.Maps.RemoveAll(m=>m.Slot==storage);room.Slot=storage;campaign.Project.Maps.Add(campaign.Read(0));}campaign.Project.CampaignSlots=episode==1?new[]{0,9}:episode==2?new[]{9,18}:new[]{0};campaign.Project.Graphics=rom.Project.Graphics;campaign.Project.Texts=rom.Project.Texts;byte[] native=campaign.Compile();campaign.SavePatch(Path.Combine(dir,"episode-"+episode+".dse"),native);Bin.Atomic(Path.Combine(dir,"episode-"+episode+".sfc"),native);}
            File.WriteAllText(Path.Combine(dir,"results.txt"),"PASS: all 18 native banks play through retail SPC driver; program mapping; long dense score auto fit; native pitched effect preview and WAV rate compensation; original maps and progression unchanged; all three episode intermission images import upright; expanded native patch/project round-trip.\r\n"+fitted.Report);
        }
    }
}
